  const allowedOwners = new Set(['src/cqc-pass40-core-metadata-variants-v1.js', 'src/cqc-pass40-core-three-metadata-variants-v1.js', 'src/cqc-pass40-support-skull-mode-v1.js', 'src/cqc-pass40-liquid-support-v1.js', 'src/cqc-pass41-support-native-cqc-v1.js', ...p42Owners, ...p43Owners, ...p44Owners]);
